def _insert_after(fields, anchor_id, field):
    """Вставляет потерянное поле сразу после связанной подсказки."""
    if any(item['id'] == field['id'] for item in fields):
        return
    index = next(i for i, item in enumerate(fields) if item['id'] == anchor_id)
    fields.insert(index + 1, field)


